/* ── tweening ─────────────────────────────────────────────── */
function tween(target, dur, token) {
  return new Promise(res => {
    const from = { yaw: state.yaw, pitch: state.pitch, roll: state.roll };
    const t0 = performance.now();
    (function step() {
      if (token !== runToken) return res(false);
      const u = Math.min(1, (performance.now() - t0) / dur);
      const e = u < 0.5 ? 2 * u * u : 1 - Math.pow(-2 * u + 2, 2) / 2;
      for (const k of ['yaw', 'pitch', 'roll']) if (k in target) state[k] = from[k] + (target[k] - from[k]) * e;
