// @FIGURE_CODE_BEGIN
// ─────────── element spec (one line per element) ───────────
// origin dot      -> SphereGeometry(0.15)                                     black
// Y axis          -> Cylinder(r .055) + Cone head      0 -> (0,4.2,0)         black
// Z axis          -> Cylinder(r .055) + Cone head      0 -> (0,0,7.2)         black
// X axis          -> Cylinder(r .055) + Cone head      0 -> (4.0,0,0)         black
// yaw arc         -> Torus(.66,.07, arc 4.5) + Cone head, about Y at y=3.40   red
// pitch arc       -> Torus(.56,.065,arc 4.5) + Cone head, about X at x=2.40   red
// roll arc        -> Torus(.56,.065,arc 4.5) + Cone head, about Z at z=5.30   red
// image plane     -> PlaneGeometry(3.4,3.4) DoubleSide, local z = 3.2         #E7EEEA .82
// plane border    -> 4 x Cylinder(r .055)                                     black
// local x axis    -> Cylinder+Cone  local (-1.45,0)->(1.45,0)                 green #00CC00
// local y axis    -> Cylinder+Cone  local (0,-1.45)->(0,1.45)                 green #00CC00
// image point p   -> Circle(.145) + Ring(.145,.20)  (ray ∩ plane)             blue #29ABE2 / black
// drop line       -> Cylinder(r .028) p -> local x axis                       gray  #9AA0A0
// world point P   -> SphereGeometry(.16) at (1.1,2.5,6.8)                     blue #29ABE2
// dashed ray      -> dash cylinders(r .034) origin -> P (passes through p)    gray  #9AA0A0
// depth polyline  -> 2 x Cylinder(r .032) P->(1.1,.9,6.8)->(0,0,6.2)          gray
// labels          -> addLabel serif: Y X Z (0,0,0) Yaw θ_Y Pitch θ_X Roll θ_Z p P x y

const BLACK = 0x111111, RED = 0xE8161C, RED_DIM = 0xEFC3C5, RED_HOT = 0xFF2A2A;
const GREEN = 0x00CC00, BLUE = 0x29ABE2, GRAY = 0x9AA0A0, DASHC = 0x9AA0A0, FILL = 0xE7EEEA;

const matBlack = new THREE.MeshBasicMaterial({ color: BLACK });
const matGray = new THREE.MeshBasicMaterial({ color: GRAY });
const matBlue = new THREE.MeshBasicMaterial({ color: BLUE });
const matGreen = new THREE.MeshBasicMaterial({ color: GREEN, depthTest: false });
const matDash = new THREE.MeshBasicMaterial({ color: DASHC, depthTest: false });
const matDrop = new THREE.MeshBasicMaterial({ color: GRAY, depthTest: false });

const Y_UP = new THREE.Vector3(0, 1, 0);

function cylBetween(a, b, r, mat) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = Math.max(dir.length(), 1e-5);
  const m = new THREE.Mesh(new THREE.CylinderGeometry(r, r, len, 14), mat);
  m.position.copy(a).add(b).multiplyScalar(0.5);
  m.quaternion.setFromUnitVectors(Y_UP, dir.clone().normalize());
  return m;
}

function arrow(a, b, r, headR, headL, mat) {
  const g = new THREE.Group();
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = dir.length();
  const u = dir.clone().normalize();
  g.add(cylBetween(a, a.clone().add(u.clone().multiplyScalar(Math.max(0.02, len - headL))), r, mat));
  const cone = new THREE.Mesh(new THREE.ConeGeometry(headR, headL, 22), mat);
  cone.position.copy(a).add(u.clone().multiplyScalar(len - headL / 2));
  cone.quaternion.setFromUnitVectors(Y_UP, u);
  g.add(cone);
  return g;
}

function dashedRay(a, b, dash, gap, r, mat) {
  const g = new THREE.Group();
  const dir = new THREE.Vector3().subVectors(b, a);
  const L = dir.length();
  const u = dir.clone().normalize();
  let t = 0;
  while (t < L) {
    const t2 = Math.min(L, t + dash);
    const p1 = a.clone().add(u.clone().multiplyScalar(t));
    const p2 = a.clone().add(u.clone().multiplyScalar(t2));
    const seg = cylBetween(p1, p2, r, mat);
    seg.renderOrder = 2;
    g.add(seg);
    t = t2 + gap;
  }
  return g;
}

function arcArrow(radius, tube, thetaStart, thetaLength) {
  const g = new THREE.Group();
  const mat = new THREE.MeshBasicMaterial({ color: RED });
  const torus = new THREE.Mesh(new THREE.TorusGeometry(radius, tube, 10, 80, thetaLength), mat);
  torus.rotation.z = thetaStart;
  g.add(torus);
  const a = thetaStart + thetaLength;
  const end = new THREE.Vector3(radius * Math.cos(a), radius * Math.sin(a), 0);
  const tan = new THREE.Vector3(-Math.sin(a), Math.cos(a), 0);
  const cone = new THREE.Mesh(new THREE.ConeGeometry(tube * 3.3, tube * 7.4, 18), mat);
  cone.position.copy(end).add(tan.clone().multiplyScalar(tube * 3.5));
  cone.quaternion.setFromUnitVectors(Y_UP, tan);
  g.add(cone);
  g.userData.mat = mat;
  return g;
}

/* ── world axes ───────────────────────────────────────────── */
const world = new THREE.Group();
scene.add(world);

world.add(new THREE.Mesh(new THREE.SphereGeometry(0.16, 20, 16), matBlack));

const O = new THREE.Vector3(0, 0, 0);
const axY = arrow(O, new THREE.Vector3(0, 4.2, 0), 0.055, 0.19, 0.5, matBlack);
const axZ = arrow(O, new THREE.Vector3(0, 0, 7.2), 0.055, 0.19, 0.5, matBlack);
const axX = arrow(O, new THREE.Vector3(4.0, 0, 0), 0.055, 0.19, 0.5, matBlack);
world.add(axY, axZ, axX);

registerInteractive(axY, { title: 'Y axis — yaw axis', tooltip: 'Vertical world axis', body: 'Rotation of the camera about the vertical Y axis is the yaw angle θ_Y. It pans the optical axis and the whole image plane left and right.' });
registerInteractive(axX, { title: 'X axis — pitch axis', tooltip: 'Lateral world axis', body: 'Rotation about the lateral X axis is the pitch angle θ_X. It tips the optical axis up and down, so the image point p moves vertically in the plane.' });
registerInteractive(axZ, { title: 'Z axis — optical axis / roll axis', tooltip: 'Optical axis', body: 'Z is the optical axis of the canonical camera. Rotation about it is the roll angle θ_Z: the image plane spins about its own centre while the ray to P is unchanged.' });

/* ── red rotation arcs ────────────────────────────────────── */
const arcYaw = arcArrow(0.66, 0.070, -0.55, 4.5);
const yawHolder = new THREE.Group();
yawHolder.add(arcYaw);
yawHolder.rotation.x = Math.PI / 2;
yawHolder.position.set(0, 3.40, 0);
world.add(yawHolder);

const arcPitch = arcArrow(0.56, 0.065, -0.9, 4.5);
const pitchHolder = new THREE.Group();
pitchHolder.add(arcPitch);
pitchHolder.rotation.y = Math.PI / 2;
pitchHolder.position.set(2.40, 0, 0);
world.add(pitchHolder);

const arcRoll = arcArrow(0.56, 0.065, -0.45, 4.5);
const rollHolder = new THREE.Group();
rollHolder.add(arcRoll);
rollHolder.position.set(0, 0, 5.30);
world.add(rollHolder);

registerInteractive(arcYaw, { title: 'Yaw θ_Y', tooltip: 'Yaw — rotation about Y', body: 'Yaw is the rotation matrix R_Y(θ_Y) about the vertical axis — the pan of a tripod head.' });
registerInteractive(arcPitch, { title: 'Pitch θ_X', tooltip: 'Pitch — rotation about X', body: 'Pitch is R_X(θ_X) about the lateral axis — tilting the camera up or down.' });
registerInteractive(arcRoll, { title: 'Roll θ_Z', tooltip: 'Roll — rotation about Z', body: 'Roll is R_Z(θ_Z) about the optical axis — the camera spins about its line of sight, rotating the image about its centre.' });

/* ── camera frame: image plane + local axes + p ───────────── */
const camGroup = new THREE.Group();
scene.add(camGroup);

const Zf = 3.2;     // focal distance along the optical axis
const HW = 1.7;     // half side of the square image plane

const planeMat = new THREE.MeshBasicMaterial({
  color: FILL, transparent: true, opacity: 0.82, side: THREE.DoubleSide,
  depthWrite: false
});
const plane = new THREE.Mesh(new THREE.PlaneGeometry(2 * HW, 2 * HW), planeMat);
plane.position.set(0, 0, Zf);
plane.renderOrder = 0;
camGroup.add(plane);
registerInteractive(plane, { title: 'Image plane', tooltip: 'Image plane (rigid with the camera)', body: 'The image plane sits at distance f along the optical axis and is rigidly attached to the camera frame. Its local axes x and y are the image coordinate axes; the world point P images at p, where the ray from the origin pierces this plane.' });

const border = new THREE.Group();
const c1 = new THREE.Vector3(-HW, -HW, Zf), c2 = new THREE.Vector3(HW, -HW, Zf);
const c3 = new THREE.Vector3(HW, HW, Zf), c4 = new THREE.Vector3(-HW, HW, Zf);
[[c1, c2], [c2, c3], [c3, c4], [c4, c1]].forEach(([a, b]) => border.add(cylBetween(a, b, 0.055, matBlack)));
camGroup.add(border);

const ZG = Zf + 0.02;
const locX = arrow(new THREE.Vector3(-1.45, 0, ZG), new THREE.Vector3(1.45, 0, ZG), 0.042, 0.135, 0.34, matGreen);
const locY = arrow(new THREE.Vector3(0, -1.45, ZG), new THREE.Vector3(0, 1.45, ZG), 0.042, 0.135, 0.34, matGreen);
locX.renderOrder = 3; locY.renderOrder = 3;
locX.traverse(o => o.renderOrder = 3); locY.traverse(o => o.renderOrder = 3);
camGroup.add(locX, locY);

// image point p (computed as ray ∩ plane)
const pGroup = new THREE.Group();
const pDiscMat = new THREE.MeshBasicMaterial({ color: BLUE, side: THREE.DoubleSide, depthTest: false });
const pRingMat = new THREE.MeshBasicMaterial({ color: BLACK, side: THREE.DoubleSide, depthTest: false });
const pDisc = new THREE.Mesh(new THREE.CircleGeometry(0.145, 30), pDiscMat);
const pRing = new THREE.Mesh(new THREE.RingGeometry(0.145, 0.20, 30), pRingMat);
pDisc.renderOrder = 5; pRing.renderOrder = 5;
pGroup.add(pDisc, pRing);
camGroup.add(pGroup);
registerInteractive(pDisc, { title: 'Image point p', tooltip: 'p = projection of P', body: 'p is the intersection of the ray from the origin to P with the image plane. Rotating the camera moves the plane, so p slides across the image even though P never moves.' });

const drop = cylBetween(new THREE.Vector3(0, -0.5, Zf + 0.03), new THREE.Vector3(0, 0.5, Zf + 0.03), 0.028, matDrop);
drop.renderOrder = 4;
camGroup.add(drop);

/* ── world point P, dashed ray, depth polyline ────────────── */
const P = new THREE.Vector3(1.1, 2.5, 6.8);
const pointP = new THREE.Mesh(new THREE.SphereGeometry(0.165, 22, 18), matBlue);
pointP.position.copy(P);
world.add(pointP);
const pOutline = new THREE.Mesh(new THREE.SphereGeometry(0.195, 22, 18),
  new THREE.MeshBasicMaterial({ color: BLACK, side: THREE.BackSide }));
pOutline.position.copy(P);
world.add(pOutline);
registerInteractive(pointP, { title: 'World point P', tooltip: 'World point P (fixed)', body: 'P is a fixed 3D point in the world frame. It never moves — only the camera rotates, which is exactly why its image p moves.' });

const ray = dashedRay(new THREE.Vector3(0, 0, 0), P.clone(), 0.24, 0.17, 0.034, matDash);
world.add(ray);
registerInteractive(ray, { title: 'Projection ray', tooltip: 'Ray origin → p → P', body: 'The dashed ray from the camera centre to P is fixed in the world. Its intersection with the rotating image plane defines the image point p.' });

const foot1 = new THREE.Vector3(1.1, 0.9, 6.8), foot2 = new THREE.Vector3(0, 0, 6.2);
world.add(cylBetween(P, foot1, 0.032, matGray));
world.add(cylBetween(foot1, foot2, 0.032, matGray));

/* ── camera view (orthographic axonometric, source-like pose) ──
   azimuth 157°, elevation 24°  →  Y projects vertical, Z nearly
   horizontal to the right, X rising diagonally up-right (~44°).   */
setCameraView({ projection: 'orthographic', azimuthDeg: 157, elevationDeg: 24, heightFraction: 0.86 });
controls.minZoom = 0.3; controls.maxZoom = 3.5;

/* ── labels ───────────────────────────────────────────────── */
const SER = "font-family:Georgia,'Times New Roman',serif;";
const S = (t, extra = '') => `<span style="${SER}${extra}">${t}</span>`;

addLabel(S('Y'), new THREE.Vector3(0, 4.2, 0), { fontSize: '24px', offset: [0, -22] });
addLabel(S('Z'), new THREE.Vector3(0, 0, 7.2), { fontSize: '24px', offset: [12, 28] });
addLabel(S('X'), new THREE.Vector3(4.0, 0, 0), { fontSize: '24px', offset: [26, -4] });
addLabel(S('(0,0,0)'), new THREE.Vector3(0, 0, 0), { fontSize: '20px', offset: [-48, 32] });

addLabel(S('Yaw'), new THREE.Vector3(0, 3.55, 0), { fontSize: '22px', offset: [-76, -10] });
addLabel(S('&theta;<sub>Y</sub>'), new THREE.Vector3(0, 2.55, 0), { fontSize: '21px', offset: [-32, 8] });
addLabel(S('Pitch'), new THREE.Vector3(2.4, 0, 0), { fontSize: '22px', offset: [-4, -62] });
addLabel(S('&theta;<sub>X</sub>'), new THREE.Vector3(2.4, 0, 0), { fontSize: '21px', offset: [-66, -10] });
addLabel(S('&theta;<sub>Z</sub>'), new THREE.Vector3(0, 0, 5.30), { fontSize: '21px', offset: [-40, -46] });
addLabel(S('Roll'), new THREE.Vector3(0, 0, 5.30), { fontSize: '22px', offset: [10, 58] });

addLabel(S('<b>P</b>'), P.clone(), { fontSize: '24px', offset: [-2, -30] });

const lblP = addLabel(S('<b>p</b>'), new THREE.Vector3(), { fontSize: '24px', offset: [-24, -22] });
const lblLx = addLabel(S('<i>x</i>'), new THREE.Vector3(), { fontSize: '24px', offset: [18, 20] });
const lblLy = addLabel(S('<i>y</i>'), new THREE.Vector3(), { fontSize: '24px', offset: [-20, 2] });

/* ── rotation state & update ──────────────────────────────── */
const state = { yaw: 0, pitch: 0, roll: 0, orderYXZ: true };
const AX = { yaw: new THREE.Vector3(0, 1, 0), pitch: new THREE.Vector3(1, 0, 0), roll: new THREE.Vector3(0, 0, 1) };
const qTmp = new THREE.Quaternion();

function localToWorld(x, y, z) { return camGroup.localToWorld(new THREE.Vector3(x, y, z)); }

function updateRotation() {
  const qY = new THREE.Quaternion().setFromAxisAngle(AX.yaw, THREE.MathUtils.degToRad(state.yaw));
  const qX = new THREE.Quaternion().setFromAxisAngle(AX.pitch, THREE.MathUtils.degToRad(state.pitch));
  const qZ = new THREE.Quaternion().setFromAxisAngle(AX.roll, THREE.MathUtils.degToRad(state.roll));
  const q = new THREE.Quaternion();
  if (state.orderYXZ) q.copy(qY).multiply(qX).multiply(qZ);
  else q.copy(qZ).multiply(qX).multiply(qY);
  camGroup.quaternion.copy(q);
  camGroup.updateMatrixWorld(true);

  // p = intersection of the fixed segment origin→P with the rotated image plane
  const n = new THREE.Vector3(0, 0, 1).applyQuaternion(q);
  const denom = P.dot(n);
  let lx = 0, ly = 0, ok = false, inside = false;
  if (Math.abs(denom) > 1e-6) {
    const t = Zf / denom;
    if (t > 0) {
      const pw = P.clone().multiplyScalar(t);
      const pl = pw.clone().applyQuaternion(qTmp.copy(q).invert());
      lx = pl.x; ly = pl.y; ok = true;
      inside = Math.abs(lx) <= HW && Math.abs(ly) <= HW;
    }
  }
  pGroup.visible = ok;
  drop.visible = ok && Math.abs(ly) > 0.03;
  lblP.div.style.visibility = ok ? 'visible' : 'hidden';
  if (ok) {
    pGroup.position.set(lx, ly, Zf + 0.05);
    pDiscMat.color.setHex(inside ? BLUE : 0xF39C12);
    drop.position.set(lx, ly / 2, Zf + 0.03);
    drop.scale.y = Math.max(Math.abs(ly), 1e-4);
    lblP.pos.copy(localToWorld(lx, ly, Zf));
  }
  lblLx.pos.copy(localToWorld(1.20, -0.22, Zf));
  lblLy.pos.copy(localToWorld(-0.30, 0.55, Zf));

  document.getElementById('pInfo').innerHTML =
    ok ? `image coords of p:&nbsp; (${lx.toFixed(2)}, ${ly.toFixed(2)})` +
      (inside ? '' : '<br><span style="color:#b35c00">p lies outside the sensor</span>')
      : '<span style="color:#b35c00">P is behind the image plane</span>';
}

/* ── UI wiring ────────────────────────────────────────────── */
const sYaw = document.getElementById('sYaw'), sPitch = document.getElementById('sPitch'), sRoll = document.getElementById('sRoll');
const vYaw = document.getElementById('vYaw'), vPitch = document.getElementById('vPitch'), vRoll = document.getElementById('vRoll');
const bOrd1 = document.getElementById('bOrd1'), bOrd2 = document.getElementById('bOrd2');

function syncSliders() {
  sYaw.value = state.yaw.toFixed(0); sPitch.value = state.pitch.toFixed(0); sRoll.value = state.roll.toFixed(0);
  vYaw.textContent = state.yaw.toFixed(0) + '\u00B0';
  vPitch.textContent = state.pitch.toFixed(0) + '\u00B0';
  vRoll.textContent = state.roll.toFixed(0) + '\u00B0';
}

let runToken = 0;
function stopAnim() { runToken++; setHighlight(null); }

function setHighlight(key) {
  const arcs = { yaw: arcYaw, pitch: arcPitch, roll: arcRoll };
  for (const k in arcs) {
    const m = arcs[k].userData.mat;
    if (!key) { m.color.setHex(RED); arcs[k].scale.setScalar(1); }
    else { m.color.setHex(k === key ? RED_HOT : RED_DIM); arcs[k].scale.setScalar(k === key ? 1.22 : 1); }
  }
}

sYaw.addEventListener('input', () => { stopAnim(); state.yaw = +sYaw.value; syncSliders(); updateRotation(); });
sPitch.addEventListener('input', () => { stopAnim(); state.pitch = +sPitch.value; syncSliders(); updateRotation(); });
sRoll.addEventListener('input', () => { stopAnim(); state.roll = +sRoll.value; syncSliders(); updateRotation(); });

function setOrder(yxz) {
  state.orderYXZ = yxz;
  bOrd1.classList.toggle('active', yxz);
  bOrd2.classList.toggle('active', !yxz);
  updateRotation();
}
bOrd1.addEventListener('click', () => { stopAnim(); setOrder(true); });
bOrd2.addEventListener('click', () => { stopAnim(); setOrder(false); });

document.getElementById('bReset').addEventListener('click', () => {
  stopAnim(); state.yaw = state.pitch = state.roll = 0; syncSliders(); updateRotation();
});

/* ── tweening ─────────────────────────────────────────────── */
function tween(target, dur, token) {
  return new Promise(res => {
    const from = { yaw: state.yaw, pitch: state.pitch, roll: state.roll };
    const t0 = performance.now();
    (function step() {
      if (token !== runToken) return res(false);
      const u = Math.min(1, (performance.now() - t0) / dur);
      const e = u < 0.5 ? 2 * u * u : 1 - Math.pow(-2 * u + 2, 2) / 2;
      for (const k of ['yaw', 'pitch', 'roll']) if (k in target) state[k] = from[k] + (target[k] - from[k]) * e;
      syncSliders(); updateRotation();
      if (u < 1) requestAnimationFrame(step); else res(true);
    })();
  });
}
function delay(ms, token) {
  return new Promise(res => setTimeout(() => res(token === runToken), ms));
}

/* ── step-through animation ───────────────────────────────── */
document.getElementById('bAnim').addEventListener('click', async () => {
  const token = ++runToken;
  const tgt = {
    yaw: Math.abs(state.yaw) > 1 ? state.yaw : 35,
    pitch: Math.abs(state.pitch) > 1 ? state.pitch : 25,
    roll: Math.abs(state.roll) > 1 ? state.roll : 40
  };
  setHighlight(null);
  if (!(await tween({ yaw: 0, pitch: 0, roll: 0 }, 450, token))) return;
  const seq = state.orderYXZ ? ['yaw', 'pitch', 'roll'] : ['roll', 'pitch', 'yaw'];
  for (const k of seq) {
    setHighlight(k);
    if (!(await tween({ [k]: tgt[k] }, 1100, token))) return;
    if (!(await delay(420, token))) return;
  }
  setHighlight(null);
});

/* ── guided demo steps ────────────────────────────────────── */
const STEPS = [
  { title: 'Canonical camera', text: 'All three Euler angles are zero. The image plane sits perpendicular to the Z (optical) axis, its local x and y axes align with world X and Y, and the dashed ray from the origin pierces the plane at p on its way to the world point P.', s: { yaw: 0, pitch: 0, roll: 0, o: true } },
  { title: 'Yaw about Y', text: 'Rotating θ_Y about the vertical axis swings the optical axis sideways. The plane turns with the camera and p slides horizontally — this is the pan of a tripod head.', s: { yaw: 35, pitch: 0, roll: 0, o: true } },
  { title: 'Add pitch about X', text: 'Now add θ_X about the lateral X axis. The camera tips upward, the plane leans back, and p moves vertically. Note that the pitch axis is the already-yawed X axis.', s: { yaw: 35, pitch: 25, roll: 0, o: true } },
  { title: 'Add roll about Z', text: 'Finally θ_Z spins the plane about its own optical axis. The ray to P is untouched, but the green local x, y axes rotate, so the image coordinates of p change.', s: { yaw: 35, pitch: 25, roll: 40, o: true } },
  { title: 'Reverse the order', text: 'Keep the same three angles but apply them roll-first. The final orientation of the plane — and the position of p — differs, showing that R = R_Y R_X R_Z is not the same as R_Z R_X R_Y.', s: { yaw: 35, pitch: 25, roll: 40, o: false } }
];
let stepIdx = 0;
const stepTitle = document.getElementById('stepTitle'), stepText = document.getElementById('stepText');

async function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const st = STEPS[stepIdx];
  stepTitle.textContent = (stepIdx + 1) + '/' + STEPS.length + '  ' + st.title;
  stepText.textContent = st.text;
  const token = ++runToken;
